    /**
     * Tests creating a new Order_.
     *
     * @return    Order_
     */
    public Order_ testCreate() throws Throwable {
    Order_ entity = null;

    LOGGER.info( "Order_Test:testCreate()" );
    LOGGER.info( "-- Attempting to create a Order_");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Order_" );

    try {
        entity = service.createOrder_( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getOrder_Id();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Order_ with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

