    /**
     * Tests getting all Order_s.
     *
     * @return    Collection
     */
    public List<Order_> testGetAll() throws Throwable {
    LOGGER.info( "Order_Test:testGetAll() - Retrieving Collection of Order_s:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Order_ : " );
    List<Order_> collection  = null;

    try {
        // call the static get method on the Order_Service
        collection = service.getAllOrder_();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Order_ currEntity  = null;
            Iterator<Order_> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOrder_Id(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

